import type { TransitNetwork, TransitStop } from '../types/commute'

const emptyNetwork: TransitNetwork = { stations: [], lineColours: {} }

// Generated by scripts/fetch-stops.mjs (npm run stops) from OpenStreetMap data.
export async function fetchMadridTransitNetwork(): Promise<TransitNetwork> {
  try {
    const response = await fetch(`${import.meta.env.BASE_URL}madrid-stops.json`)
    if (!response.ok) {
      return emptyNetwork
    }
    const data = (await response.json()) as { stations: TransitStop[]; lines: Record<string, string> }
    return { stations: data.stations, lineColours: data.lines }
  } catch {
    return emptyNetwork
  }
}

// Maps a ride label from routing ("Metro 4", "C2", "Metro Ligero 2") to a line ref ("L4", "C2", "ML2").
export function lineRefForRide(ride: string): string | null {
  const metro = /^Metro (\d+|R)$/i.exec(ride)
  if (metro) return metro[1] === 'R' ? 'R' : `L${metro[1]}`
  const light = /^Metro Ligero (?:ML)?(\d+)$/i.exec(ride)
  if (light) return `ML${light[1]}`
  const cercanias = /^C-?(\d+[ab]?)$/i.exec(ride)
  if (cercanias) return `C${cercanias[1].toUpperCase()}`
  return null
}
